export const RhpfLogoSvg = FondoHumanitarioSvg;

// Generic Partner / Ministry Logo
export const PartnerLogoSvg: React.FC<{
  name: string;
  variant?: 'color' | 'white' | 'dark' | 'monochrome';
  className?: string;
  customColor?: string;
}> = ({ name, variant = 'color', className = 'h-10', customColor }) => {
  const isWhite = variant === 'white';
  const borderColor = customColor
    ? `${customColor}40`
    : isWhite
    ? 'rgba(255,255,255,0.4)'
    : 'rgba(0,0,0,0.15)';
  const textColor = customColor ? customColor : isWhite ? '#FFFFFF' : '#334155';

  return (
    <div
      className={`flex items-center gap-2 px-2.5 py-1 rounded border text-left select-none ${className}`}
      style={{ borderColor }}
    >
      <div className="w-6 h-6 rounded-full bg-slate-300/30 flex items-center justify-center shrink-0">
        <span className="text-[10px] font-bold" style={{ color: textColor }}>
          🏛️
        </span>
      </div>
      <div className="flex flex-col text-[8.5px] leading-tight max-w-[150px] font-roboto" style={{ color: textColor }}>
        <span className="font-semibold line-clamp-2">{name}</span>
        <span className="text-[7.5px] opacity-70">Socio Implementador</span>
      </div>
    </div>
  );
};

/**
 * Universal Dynamic Logo Renderer:
 * Handles:
 * - Custom Uploaded PNG/JPG (with CSS white/dark filter when monochrome/white is selected)
 * - Official SVG ACH (supports 'white', 'color', 'dark', 'monochrome')
 * - Official SVG Fondo Humanitario (supports 'white', 'color', 'dark', 'monochrome')
 * - Partner logos
 */
export const DynamicLogoRenderer: React.FC<{
  logo: LogoItem;
  variant?: 'color' | 'white' | 'dark' | 'monochrome';
  className?: string;
  overrideColorMode?: 'auto' | 'white' | 'color' | 'monochrome';
}> = ({ logo, variant = 'color', className = 'h-9 max-h-11', overrideColorMode = 'auto' }) => {
  const effectiveVariant =
    overrideColorMode !== 'auto'
      ? overrideColorMode
      : logo.variant || variant;

  if (logo.url) {
    let imgFilterStyle = {};
    if (effectiveVariant === 'white') {
      imgFilterStyle = { filter: 'brightness(0) invert(1)' };
    } else if (effectiveVariant === 'dark' || effectiveVariant === 'monochrome') {
      imgFilterStyle = { filter: 'grayscale(1) contrast(1.2)' };
    }

    return (
      <img
        src={logo.url}
        alt={logo.name}
        style={imgFilterStyle}
        className={`object-contain max-w-[140px] drop-shadow-sm select-none transition-all ${className}`}
      />
    );
  }

  if (logo.id === 'logo-ach' || logo.type === 'ach') {
    return <AchOfficialSvg variant={effectiveVariant} className={className} />;
  }

  if (
    logo.id === 'logo-rhpf' ||
    logo.id === 'logo-fondo-humanitario' ||
    logo.name.toLowerCase().includes('fondo') ||
    logo.name.toLowerCase().includes('rhpf')
  ) {
    return <FondoHumanitarioSvg variant={effectiveVariant} className={className} />;
  }

  return <PartnerLogoSvg name={logo.name} variant={effectiveVariant} className={className} />;
};
